[{"order":1,"type":"heading","text":"Bridging Third-Party Native SDKs in React Native"},{"order":2,"type":"paragraph","text":"React Native empowers developers to build cross-platform mobile applications using JavaScript and TypeScript. However, certain enterprise-grade features require deep integration with native iOS (Swift/Objective-C) and Android (Kotlin/Java) SDKs, such as Firebase, advanced Payment Gateways, and low-level Bluetooth peripherals."},{"order":3,"type":"subheading","text":"Understanding the React Native Bridge Architecture"},{"order":4,"type":"paragraph","text":"Before building custom native modules, it is essential to understand how JavaScript communicates with the native thread. React Native utilizes a bridge to pass asynchronous JSON messages between the JS engine and native modules. In newer versions of React Native, the architecture is evolving towards JSI (JavaScript Interface), allowing direct synchronous calls to C++ host objects."},{"order":5,"type":"subheading","text":"Step 1: Implementing a Native Module for Android (Kotlin)"},{"order":6,"type":"paragraph","text":"To expose native Android functionality to React Native, you need to extend ReactContextBaseJavaModule and annotate your methods with @ReactMethod."},{"order":7,"type":"code","text":"package com.mycompany.nativemodule

import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod
import com.facebook.react.bridge.Promise

class PaymentModule(reactContext: ReactApplicationContext) : ReactContextBaseJavaModule(reactContext) {
    override fun getName() = "PaymentModule"

    @ReactMethod
    fun processPayment(amount: Double, promise: Promise) {
        try {
            // Integrate Payment Gateway SDK logic here
            val transactionId = "TXN_123456"
            promise.resolve(transactionId)
        } catch (e: Exception) {
            promise.reject("PAYMENT_ERROR", e.localizedMessage, e)
        }
    }
}"},{"order":8,"type":"subheading","text":"Step 2: Implementing a Native Module for iOS (Swift)"},{"order":9,"type":"paragraph","text":"For iOS, you create a Swift class that bridges to Objective-C macros using RCT_EXTERN_MODULE to expose methods to the React Native runtime."},{"order":10,"type":"code","text":"import Foundation
import React

@objc(PaymentModule)
class PaymentModule: NSObject {

    @objc
    func constantsToExport() -> [String: Any] {
        return ["SDK_VERSION": "2.1.0"]
    }

    @objc
    func processPayment(_ amount: Double, resolver resolve: @escaping RCTPromiseResolveBlock, rejecter reject: @escaping RCTPromiseRejectBlock) {
        // Integrate iOS Payment Gateway SDK
        let transactionId = "TXN_123456"
        resolve(transactionId)
    }

    @objc
    static func requiresMainQueueSetup() -> Bool {
        return true
    }
}"},{"order":11,"type":"subheading","text":"Step 3: Creating the JavaScript Wrapper"},{"order":12,"type":"paragraph","text":"Once the native modules are created for both platforms, wrap them in a clean TypeScript/JavaScript module to consume them safely in your React Native components."},{"order":13,"type":"code","text":"import { NativeModules, Platform } from 'react-native';

interface PaymentInterface {
  processPayment(amount: number): Promise<string>;
  SDK_VERSION: string;
}

const { PaymentModule } = NativeModules;

export const PaymentService: PaymentInterface = {
  processPayment: async (amount: number): Promise<string> => {
    try {
      const txId = await PaymentModule.processPayment(amount);
      return txId;
    } catch (error) {
      throw new Error(`Payment failed: ${error}`);
    }
  },
  SDK_VERSION: PaymentModule.SDK_VERSION || '1.0.0',
};"},{"order":14,"type":"subheading","text":"Best Practices for SDK Integration"},{"order":15,"type":"bullet_point","text":"Use existing community packages (like @react-native-firebase/app) before writing custom bridges for massive SDKs."},{"order":16,"type":"bullet_point","text":"Always handle lifecycle events gracefully, especially for continuous streams like Bluetooth scanning or Firebase push notifications."},{"order":17,"type":"bullet_point","text":"Leverage Promises or NativeEventEmitter for asynchronous communication to prevent blocking the UI thread."}]
